// ===== SETTINGS ===================================================================================
const SETTINGS = {
  invoice_technique: 'few_shot',     // prompt technique of the invoice agent (best in the evaluation)
  slack_enabled: false,              // true once a Slack credential is set on the two Slack nodes
  slack_channel: 'claims-review',    // channel name (without #) for review requests and fraud alerts
};
// ==================================================================================================
// One claim format for both entry points (the form and the authenticated API), and the files sorted:
// images -> photo_0, photo_1, ... ; the repair invoice (PDF, or a file whose name says invoice/facture) -> invoice.
const item = $input.first();
const j = item.json || {};
const fromApi = j.headers !== undefined && j.body !== undefined;
const body = fromApi ? (j.body || {}) : j;
const pick = (...keys) => {
  for (const k of keys) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '' && typeof v !== 'object') return v;
  }
  return undefined;
};
const isInvoiceName = (s) => /invoice|facture|repair/i.test(s || '');
const isImage = (b) => /^image\//i.test(b.mimeType || '') || /\.(jpe?g|png|webp)$/i.test(b.fileName || '');
const isPdf = (b) => /pdf/i.test(b.mimeType || '') || /\.pdf$/i.test(b.fileName || '');
const files = Object.entries(item.binary || {});
let invoiceEntry = files.find(([k, b]) => isInvoiceName(k) || isInvoiceName(b.fileName)) || files.find(([, b]) => isPdf(b));
const binary = {};
let n = 0;
for (const [k, b] of files) {
  if (invoiceEntry && k === invoiceEntry[0]) continue;
  if (isImage(b)) binary[`photo_${n++}`] = b;
}
if (invoiceEntry) binary.invoice = invoiceEntry[1];

const now = new Date();
const amount = pick('claimed_amount', 'Claimed amount (TND)');
const date = pick('incident_date', 'Incident date');
const claim = {
  claim_id: String(pick('claim_id') || `CLM-${now.toISOString().slice(0, 10).replace(/-/g, '')}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`),
  policy_id: String(pick('policy_id', 'Policy ID') ?? '').trim().toUpperCase(),
  incident_date: date ? String(date).slice(0, 10) : undefined,
  incident_location: String(pick('incident_location', 'Incident location') ?? ''),
  description: String(pick('description', 'Description of the accident') ?? ''),
  claimed_amount: amount !== undefined ? Number(String(amount).replace(',', '.')) : undefined,
  photo_count: n,
  has_invoice: !!invoiceEntry,
  source: fromApi ? 'api' : 'form',
  submitted_at: now.toISOString(),
};
return [{ json: { claim, settings: SETTINGS }, binary }];

// Two photo checks that no agent does (design 4.6):
//  - the date each photo was taken, read from its EXIF data  -> PHOTO_BEFORE_INCIDENT rule (+15)
//  - a fingerprint of the file, compared later with all earlier claims -> PHOTO_REUSED rule (+40)
const item = $input.first();
const checks = [];
for (const key of Object.keys(item.binary || {}).filter((k) => k.startsWith('photo_'))) {
  const buf = await this.helpers.getBinaryDataBuffer(0, key);
  // 64-bit fingerprint (two FNV-1a passes): the same file always gives the same value
  let a = 0x811c9dc5, b = 0x01000193 ^ buf.length;
  for (let i = 0; i < buf.length; i++) {
    a = Math.imul(a ^ buf[i], 16777619) >>> 0;
    b = Math.imul(b ^ buf[buf.length - 1 - i], 16777619) >>> 0;
  }
  const fingerprint = `${a.toString(16).padStart(8, '0')}${b.toString(16).padStart(8, '0')}-${buf.length}`;
  // EXIF dates are plain text "YYYY:MM:DD HH:MM:SS" at the start of a JPEG; the earliest one is the shot
  const head = buf.subarray(0, Math.min(buf.length, 131072)).toString('latin1');
  const dates = [...head.matchAll(/(\d{4}):(\d{2}):(\d{2}) \d{2}:\d{2}:\d{2}/g)]
    .map((m) => `${m[1]}-${m[2]}-${m[3]}`)
    .filter((d) => d >= '1995-01-01' && !Number.isNaN(Date.parse(d)))
    .sort();
  checks.push({ key, file_name: item.binary[key].fileName || key, fingerprint, taken_date: dates[0] || null });
}
return [{ json: { ...item.json, photo_checks: checks }, binary: item.binary }];

// Compare the photo fingerprints with the photos of every earlier claim (data/claimshield/photo_register.json).
const P = $('Photo Checks').first();
let register = [];
try {
  if ($input.first().binary?.data) {
    const r = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'));
    if (Array.isArray(r)) register = r;
  }
} catch (e) { register = []; }   // no register yet (first claim) or unreadable: nothing to compare
const claim = { ...P.json.claim };
const checks = P.json.photo_checks || [];
const reuse = [];
for (const c of checks) {
  const hit = register.find((r) => r.fingerprint === c.fingerprint && r.claim_id !== claim.claim_id);
  if (hit) reuse.push({ file_name: c.file_name, already_used_in: hit.claim_id });
}
claim.photo_taken_dates = checks.map((c) => c.taken_date).filter(Boolean);
claim.photo_reused = reuse.length > 0;
return [{ json: { ...P.json, claim, photo_reuse: reuse, photo_register: register }, binary: P.binary }];

// Visual Inspection Agent input: the claim fields it uses + only the photos (it analyses every file it receives).
const R = $('Register Check').first();
const c = R.json.claim;
const binary = Object.fromEntries(Object.entries(R.binary || {}).filter(([k]) => k.startsWith('photo_')));
return [{ json: { claim_id: c.claim_id, description: c.description, incident_date: c.incident_date, photo_count: c.photo_count }, binary }];

// Invoice Parser Agent input: the claim (for its fraud signals) + the invoice file only.
const R = $('Register Check').first();
const c = R.json.claim;
const json = {
  claim: { claim_id: c.claim_id, claimed_amount: c.claimed_amount, incident_date: c.incident_date },
  technique: R.json.settings.invoice_technique,
};
if (!R.binary?.invoice) json.invoice_path = '/data/claimshield/no_invoice_sent.pdf';   // agent answers { error: true }
return [{ json, binary: R.binary?.invoice ? { invoice: R.binary.invoice } : {} }];

// Policy RAG Agent input: description, the customer's product, the parts seen on the photos and on the invoice.
const out = (name) => {
  const j = $(name).first().json;
  return j && Object.keys(j).length ? j : { error: true, reason: `${name}: no output` };
};
return [{ json: {
  claim: $('Register Check').first().json.claim,
  policy: $('Validate Claim').first().json.policy,
  visual: out('Visual Inspection'),
  invoice: out('Invoice Parser'),
} }];

// Stage 2 of the decision agent: everything the agents found. The invoice is reduced to the contract fields
// (the full extraction is kept in the audit log, not sent to the LLM).
const out = (name) => {
  const j = $(name).first().json;
  return j && Object.keys(j).length ? j : { error: true, reason: `${name}: no output` };
};
const inv = out('Invoice Parser');
const invoice = inv.error ? inv : {
  totals_match: inv.totals_match, arithmetic_issue: inv.arithmetic_issue, line_items: inv.line_items,
  status: inv.status, review_reasons: inv.review_reasons, warnings: inv.warnings,
  amount_matches_claim: inv.amount_matches_claim, total: inv.invoice?.total, currency: inv.invoice?.currency,
};
return [{ json: {
  stage: 'decide',
  claim: $('Register Check').first().json.claim,
  validation: $('Validate Claim').first().json,
  visual: out('Visual Inspection'),
  invoice,
  policy_rag: out('Policy RAG'),
} }];

// ---- shared by Decision Record and Rejected Record: result page and Slack texts
const LABEL = { auto_approve: 'APPROVED', human_review: 'HUMAN REVIEW', fraud_investigation: 'FRAUD INVESTIGATION', rejected: 'REJECTED' };
const CUSTOMER = {
  auto_approve: (r) => `Your claim ${r.claim_id} is approved. A payment request of ${r.payout_proposed ?? '-'} TND (after the deductible) has been sent.`,
  human_review: (r) => `Your claim ${r.claim_id} has been received and is being reviewed by an adjuster. You will be contacted within 2 working days.`,
  // customer messages never mention suspected fraud (design 4.8)
  fraud_investigation: (r) => `Your claim ${r.claim_id} has been received and needs additional checks by our team. You will be contacted soon.`,
  rejected: (r) => `Your claim ${r.claim_id} cannot be accepted: ${r.route_reasons.join('; ')}.`,
};
function finish(r, settings) {
  const signs = (r.warning_signs || []).map((s) => `${s.code} (+${s.points}): ${s.detail}`);
  const internal = [
    `Route: ${LABEL[r.route] || r.route}` + (r.risk_score != null ? ` | risk score ${r.risk_score}/100 (rules ${r.rule_score} + AI ${r.llm_adjustment})` : ''),
    `Warning signs: ${signs.length ? signs.join(' | ') : 'none'}`,
    r.coverage?.status ? `Coverage: ${r.coverage.status}${(r.coverage.cited_clauses || []).length ? ` (${r.coverage.cited_clauses.join(', ')})` : ''}` : null,
    `Reasons: ${(r.route_reasons || []).join('; ') || '-'}`,
    r.justification ? `AI assessment: ${r.justification}` : null,
    `Processed in ${r.processing_seconds} s`,
  ].filter(Boolean);
  const page = {
    title: `Claim ${r.claim_id} - ${LABEL[r.route] || r.route}`,
    message: `${CUSTOMER[r.route] ? CUSTOMER[r.route](r) : ''}\n\n--- Internal summary (adjuster only) ---\n${internal.join('\n')}`,
  };
  const head = `Claim ${r.claim_id} | policy ${r.claim.policy_id} | ${r.claim.claimed_amount} TND`;
  const slack = {
    review_message: `*Human review needed* - ${head}\n${internal.join('\n')}\nDescription: ${r.claim.description}`,
    fraud_message: `:rotating_light: *Fraud investigation* - ${head}\n${internal.join('\n')}`,
  };
  return [{ json: { ...r, settings, page, slack } }];
}

// The decision record (design 4.7) + everything needed for the audit log, the result page and Slack.
const R = $('Register Check').first().json;
const input = $('Decision Input').first().json;
const d = $input.first().json || {};
const ok = typeof d.route === 'string';
const policy = input.validation?.policy || {};
const amount = Number(R.claim.claimed_amount);
const route = ok ? d.route : 'human_review';
const payout = route === 'auto_approve'
  ? Math.round(Math.max(0, Math.min(amount - (policy.deductible || 0), policy.coverage_limit ?? Infinity)) * 1000) / 1000 : null;
const record = {
  claim_id: R.claim.claim_id,
  decided_at: new Date().toISOString(),
  processing_seconds: Math.round((Date.now() - Date.parse(R.claim.submitted_at)) / 100) / 10,
  route,
  risk_score: ok ? d.risk_score : null,
  rule_score: ok ? d.rule_score : null,
  llm_adjustment: ok ? d.llm_adjustment : null,
  warning_signs: ok ? d.warning_signs : [],
  route_reasons: ok ? d.route_reasons : [`Decision agent failed: ${String(d.error ?? 'no output')}`],
  coverage: ok ? d.coverage : {},
  justification: ok ? d.justification : '',
  additional_concerns: ok ? d.additional_concerns : [],
  missing_inputs: ok ? d.missing_inputs : [],
  payout_proposed: payout,
  claim: R.claim,
  policy: { policy_id: policy.policy_id, product: policy.product, deductible: policy.deductible,
            coverage_limit: policy.coverage_limit, auto_approval_limit: policy.auto_approval_limit },
  photo_reuse: R.photo_reuse,
  agents: { visual: input.visual, invoice: $('Invoice Parser').first().json, policy_rag: input.policy_rag },
};
return finish(record, R.settings);

// ---- shared by Decision Record and Rejected Record: result page and Slack texts
const LABEL = { auto_approve: 'APPROVED', human_review: 'HUMAN REVIEW', fraud_investigation: 'FRAUD INVESTIGATION', rejected: 'REJECTED' };
const CUSTOMER = {
  auto_approve: (r) => `Your claim ${r.claim_id} is approved. A payment request of ${r.payout_proposed ?? '-'} TND (after the deductible) has been sent.`,
  human_review: (r) => `Your claim ${r.claim_id} has been received and is being reviewed by an adjuster. You will be contacted within 2 working days.`,
  // customer messages never mention suspected fraud (design 4.8)
  fraud_investigation: (r) => `Your claim ${r.claim_id} has been received and needs additional checks by our team. You will be contacted soon.`,
  rejected: (r) => `Your claim ${r.claim_id} cannot be accepted: ${r.route_reasons.join('; ')}.`,
};
function finish(r, settings) {
  const signs = (r.warning_signs || []).map((s) => `${s.code} (+${s.points}): ${s.detail}`);
  const internal = [
    `Route: ${LABEL[r.route] || r.route}` + (r.risk_score != null ? ` | risk score ${r.risk_score}/100 (rules ${r.rule_score} + AI ${r.llm_adjustment})` : ''),
    `Warning signs: ${signs.length ? signs.join(' | ') : 'none'}`,
    r.coverage?.status ? `Coverage: ${r.coverage.status}${(r.coverage.cited_clauses || []).length ? ` (${r.coverage.cited_clauses.join(', ')})` : ''}` : null,
    `Reasons: ${(r.route_reasons || []).join('; ') || '-'}`,
    r.justification ? `AI assessment: ${r.justification}` : null,
    `Processed in ${r.processing_seconds} s`,
  ].filter(Boolean);
  const page = {
    title: `Claim ${r.claim_id} - ${LABEL[r.route] || r.route}`,
    message: `${CUSTOMER[r.route] ? CUSTOMER[r.route](r) : ''}\n\n--- Internal summary (adjuster only) ---\n${internal.join('\n')}`,
  };
  const head = `Claim ${r.claim_id} | policy ${r.claim.policy_id} | ${r.claim.claimed_amount} TND`;
  const slack = {
    review_message: `*Human review needed* - ${head}\n${internal.join('\n')}\nDescription: ${r.claim.description}`,
    fraud_message: `:rotating_light: *Fraud investigation* - ${head}\n${internal.join('\n')}`,
  };
  return [{ json: { ...r, settings, page, slack } }];
}

// A claim rejected by the validation stage (missing field, unknown or inactive policy, incident outside
// the coverage period): no AI call was made.
const R = $('Register Check').first().json;
const v = $input.first().json || {};
const record = {
  claim_id: R.claim.claim_id,
  decided_at: new Date().toISOString(),
  processing_seconds: Math.round((Date.now() - Date.parse(R.claim.submitted_at)) / 100) / 10,
  route: 'rejected',
  risk_score: null, rule_score: null, llm_adjustment: null, warning_signs: [],
  route_reasons: v.reasons?.length ? v.reasons : [`Validation failed: ${String(v.error ?? 'no output')}`],
  coverage: {}, justification: '', additional_concerns: [], missing_inputs: [], payout_proposed: null,
  claim: R.claim, policy: v.policy || null, photo_reuse: R.photo_reuse, agents: {},
};
return finish(record, R.settings);

// One JSON line per claim in data/claimshield/decisions_log.jsonl (audit trail: every agent result is kept).
const { page, slack, settings, ...record } = $input.first().json;
const line = JSON.stringify({ type: 'decision', ...record }) + '\n';
return [{ json: { claim_id: record.claim_id, route: record.route },
          binary: { log: { data: Buffer.from(line, 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: 'decisions_log.jsonl' } } }];

// Add this claim's photos to the register so a later claim reusing them is detected.
const r = $input.first().json;
const R = $('Register Check').first().json;
const register = [...(R.photo_register || [])];
for (const c of R.photo_checks || []) {
  if (!register.some((x) => x.fingerprint === c.fingerprint && x.claim_id === r.claim_id)) {
    register.push({ fingerprint: c.fingerprint, claim_id: r.claim_id, file_name: c.file_name, taken_date: c.taken_date, added_at: new Date().toISOString() });
  }
}
return [{ json: { photos_in_register: register.length },
          binary: { register: { data: Buffer.from(JSON.stringify(register, null, 1), 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'photo_register.json' } } }];

// Mock payment endpoint (real payments are out of scope, design 1.3): the request is recorded only.
const r = $input.first().json;
return [{ json: { payment_request: { claim_id: r.claim_id, amount: r.payout_proposed, currency: 'TND', status: 'mock_sent', at: new Date().toISOString() } } }];

// The adjuster's answer on Slack is added to the audit log.
const r = $('Decision Record').first().json;
const approved = $json.data?.approved;
const answer = approved === true ? 'approved' : approved === false ? 'rejected' : 'no_answer';
const line = JSON.stringify({ type: 'adjuster_answer', claim_id: r.claim_id, answer, at: new Date().toISOString() }) + '\n';
return [{ json: { claim_id: r.claim_id, adjuster_answer: answer },
          binary: { log: { data: Buffer.from(line, 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: 'decisions_log.jsonl' } } }];
